require_once '../config/database.php';require_once '../config/response.php';$c=trim($_GET['codigo']??'');if($c==='')jsonResponse(false,'Informe o código.',[],400);$s=$conn->prepare('SELECT id,codigo,cliente_nome,origem,destino,data_saida,passageiros,tipo,status,valor FROM viagens WHERE empresa_id=3 AND codigo=? LIMIT 1');$s->bind_param('s',$c);$s->execute();$v=$s->get_result()->fetch_assoc();if(!$v)jsonResponse(false,'Viagem não encontrada.',[],404);$id=(int)$v['id'];$h=$conn->prepare('SELECT status_novo,observacao,criado_em FROM viagens_historico WHERE viagem_id=? ORDER BY id');$h->bind_param('i',$id);$h->execute();$v['historico']=$h->get_result()->fetch_all(MYSQLI_ASSOC);jsonResponse(true,'',['viagem'=>$v]);
